import {b,fmt,clamp,shells,heating,work,buoyancy,pendulum,falling} from '../math.js';
import {C,reflect,read,particles,molecule,atom,cell,neuron,plants,organelles} from '../scene-utils.js';
export default ({g,t,p})=>{let tau=p[0],cycle=t%2.5,q=Math.min(cycle/tau,1),shift=.5*3*tau*tau;g.box(0,.7,0,.3,.4,.32,C.blue);g.box(q*1.3,.15,0,.8,.02,.4,C.green);let x=cycle<tau?.5*3*cycle*cycle:shift+3*tau*(cycle-tau),y=cycle<tau?-.02:Math.min(.8,-.02+2*(cycle-tau)**2);g.sphere(x,y,0,.1,C.gold);return[read('Contact time','सम्पर्क समय',fmt(tau),'s'),read('Illustrative frictional Δv','सांकेतिक घर्षणीय Δv',fmt(3*tau),'m/s'),{label:b('Observation','अवलोकन'),value:tau<.3?b('Short impulse: coin stays near its starting position','कम आवेग: सिक्का आरम्भिक स्थान के पास'):b('Longer contact: more horizontal motion','लम्बा सम्पर्क: अधिक क्षैतिज गति')}];};
